arguments.file_text:
namespace sv_009b5a4efa4b41ad8b683981d1471569.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@page "/settings"
@using sv_009b5a4efa4b41ad8b683981d1471569.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard d-flex">
    <!-- Left sidebar navigation -->
    <nav class="settings-sidebar">
        <ul class="nav flex-column">
            @foreach (var section in _sections)
            {
                <li class="nav-item">
                    <button class="nav-link @(ActiveSection == section.Key ? "active" : "")"
                            @onclick="() => SetActiveSection(section.Key)">
                        <span class="section-icon">@section.Value.Icon</span>
                        @section.Value.Label
                    </button>
                </li>
            }
        </ul>
    </nav>

    <!-- Main content area -->
    <main class="settings-content flex-grow-1">
        @if (_loading)
        {
            <div class="d-flex justify-content-center p-5">
                <div class="spinner-border" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            @switch (ActiveSection)
            {
                case "profile":
                    <ProfileSection Profile="_profile"
                                    SavedProfile="_savedProfile"
                                    OnSave="SaveProfile"
                                    OnDiscard="DiscardProfileChanges" />
                    break;
                case "notifications":
                    <NotificationsSection Prefs="_notificationPrefs"
                                          OnSave="SaveNotifications" />
                    break;
                case "security":
                    <SecuritySection Settings="_securitySettings"
                                     OnChangePassword="ChangePassword"
                                     OnRevokeSession="RevokeSession" />
                    break;
                case "appearance":
                    <AppearanceSection Settings="_appearanceSettings"
                                       OnSave="SaveAppearance" />
                    break;
            }
        }

        @if (!string.IsNullOrEmpty(_toastMessage))
        {
            <div class="toast-notification @(_toastIsError ? "toast-error" : "toast-success")">
                @_toastMessage
            </div>
        }
    </main>
</div>

@code {
    private string ActiveSection { get; set; } = "profile";
    private bool _loading = true;
    private string? _toastMessage;
    private bool _toastIsError;
    private CancellationTokenSource? _toastCts;

    private UserProfile _profile = new("", "", "", "");
    private UserProfile _savedProfile = new("", "", "", "");
    private NotificationPrefs _notificationPrefs = new(false, false, false, new());
    private SecuritySettings _securitySettings = new(false, null, new());
    private AppearanceSettings _appearanceSettings = new("System", "Medium", "English", false);

    private readonly Dictionary<string, (string Label, string Icon)> _sections = new()
    {
        ["profile"] = ("Profile", "👤"),
        ["notifications"] = ("Notifications", "🔔"),
        ["security"] = ("Security", "🔒"),
        ["appearance"] = ("Appearance", "🎨")
    };

    protected override async Task OnInitializedAsync()
    {
        await LoadSectionData("profile");
        _loading = false;
    }

    private async Task SetActiveSection(string section)
    {
        ActiveSection = section;
        _loading = true;
        await LoadSectionData(section);
        _loading = false;
    }

    private async Task LoadSectionData(string section)
    {
        switch (section)
        {
            case "profile":
                _savedProfile = await SettingsService.GetProfileAsync();
                _profile = _savedProfile with { };
                break;
            case "notifications":
                _notificationPrefs = await SettingsService.GetNotificationPrefsAsync();
                break;
            case "security":
                _securitySettings = await SettingsService.GetSecuritySettingsAsync();
                break;
            case "appearance":
                _appearanceSettings = await SettingsService.GetAppearanceAsync();
                break;
        }
    }

    private async Task SaveProfile(UserProfile profile)
    {
        try
        {
            await SettingsService.SaveProfileAsync(profile);
            _savedProfile = profile with { };
            _profile = profile with { };
            await ShowToast("Profile saved successfully!");
        }
        catch (Exception ex)
        {
            await ShowToast($"Error saving profile: {ex.Message}", isError: true);
        }
    }

    private Task DiscardProfileChanges()
    {
        _profile = _savedProfile with { };
        StateHasChanged();
        return Task.CompletedTask;
    }

    private async Task SaveNotifications(NotificationPrefs prefs)
    {
        try
        {
            await SettingsService.SaveNotificationPrefsAsync(prefs);
            _notificationPrefs = prefs;
            await ShowToast("Notification preferences saved!");
        }
        catch (Exception ex)
        {
            await ShowToast($"Error saving preferences: {ex.Message}", isError: true);
        }
    }

    private async Task ChangePassword((string Current, string New) passwords)
    {
        try
        {
            await SettingsService.ChangePasswordAsync(passwords.Current, passwords.New);
            await ShowToast("Password updated successfully!");
        }
        catch (Exception ex)
        {
            await ShowToast($"Error changing password: {ex.Message}", isError: true);
        }
    }

    private async Task RevokeSession(string sessionId)
    {
        try
        {
            await SettingsService.RevokeSessionAsync(sessionId);
            _securitySettings = await SettingsService.GetSecuritySettingsAsync();
            await ShowToast("Session revoked successfully!");
        }
        catch (Exception ex)
        {
            await ShowToast($"Error revoking session: {ex.Message}", isError: true);
        }
    }

    private async Task SaveAppearance(AppearanceSettings settings)
    {
        try
        {
            await SettingsService.SaveAppearanceAsync(settings);
            _appearanceSettings = settings;
            await ShowToast("Appearance settings saved!");
        }
        catch (Exception ex)
        {
            await ShowToast($"Error saving appearance: {ex.Message}", isError: true);
        }
    }

    private async Task ShowToast(string message, bool isError = false)
    {
        _toastCts?.Cancel();
        _toastCts = new CancellationTokenSource();
        var token = _toastCts.Token;

        _toastMessage = message;
        _toastIsError = isError;
        StateHasChanged();

        try
        {
            await Task.Delay(3000, token);
            _toastMessage = null;
            StateHasChanged();
        }
        catch (TaskCanceledException) { }
    }
}

