+@code {
+    private string ActiveSection { get; set; } = "profile";
+    private bool _loading = true;
+    private string? _toastMessage;
+    private bool _toastIsError;
+    private CancellationTokenSource? _toastCts;
+
+    private UserProfile _profile = new("", "", "", "");
+    private UserProfile _savedProfile = new("", "", "", "");
+    private NotificationPrefs _notificationPrefs = new(false, false, false, new());
+    private SecuritySettings _securitySettings = new(false, null, new());
+    private AppearanceSettings _appearanceSettings = new("System", "Medium", "English", false);
+
+    private readonly Dictionary<string, (string Label, string Icon)> _sections = new()
