@using sv_009b5a4efa4b41ad8b683981d1471569.Services

<section class="settings-section">
    <h2>Profile Settings</h2>

    <div class="mb-3">
        <div class="avatar-preview">
            @if (!string.IsNullOrWhiteSpace(_displayAvatarUrl))
            {
                <img src="@_displayAvatarUrl" alt="Avatar" class="avatar-image" />
            }
            else
            {
                <div class="avatar-placeholder">No Avatar</div>
            }
        </div>
        <label class="form-label">Avatar URL</label>
        <input type="url" class="form-control" value="@_avatarUrl"
               @onchange="e => _avatarUrl = e.Value?.ToString() ?? string.Empty" />
    </div>

    <div class="mb-3">
        <label class="form-label">Display Name</label>
        <input type="text" class="form-control" @bind="_displayName" />
    </div>

    <div class="mb-3">
        <label class="form-label">Email</label>
        <input type="email" class="form-control" @bind="_email" />
    </div>

    <div class="mb-3">
        <label class="form-label">Bio</label>
        <textarea class="form-control" rows="4" @bind="_bio"></textarea>
    </div>

    <div class="d-flex gap-2">
        <button class="btn btn-primary" @onclick="Save">Save Changes</button>
        <button class="btn btn-outline-secondary" @onclick="Discard">Discard Changes</button>
    </div>
</section>

@code {
    [Parameter] public UserProfile Profile { get; set; } = default!;
    [Parameter] public UserProfile SavedProfile { get; set; } = default!;
    [Parameter] public EventCallback<UserProfile> OnSave { get; set; }
    [Parameter] public EventCallback OnDiscard { get; set; }

    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";
    private string _displayAvatarUrl = "";

    protected override void OnParametersSet()
    {
        _displayName = Profile.DisplayName;
        _email = Profile.Email;
        _avatarUrl = Profile.AvatarUrl;
        _bio = Profile.Bio;
        _displayAvatarUrl = Profile.AvatarUrl;
    }

    private async Task Save()
    {
        var updated = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await OnSave.InvokeAsync(updated);
        _displayAvatarUrl = _avatarUrl;
    }

    private async Task Discard()
    {
        await OnDiscard.InvokeAsync();
    }
}

@using sv_009b5a4efa4b41ad8b683981d1471569.Services

<section class="settings-section">
    <h2>Notification Preferences</h2>

    <div class="mb-3">
        <div class="form-check form-switch">
            <input class="form-check-input" type="checkbox" id="emailNotif"
                   checked="@_emailNotifications"
                   @onchange="e => _emailNotifications = (bool)(e.Value ?? false)" />
            <label class="form-check-label" for="emailNotif">Email Notifications</label>
        </div>
    </div>

    <div class="mb-3">
        <div class="form-check form-switch">
            <input class="form-check-input" type="checkbox" id="pushNotif"
                   checked="@_pushNotifications"
                   @onchange="e => _pushNotifications = (bool)(e.Value ?? false)" />
            <label class="form-check-label" for="pushNotif">Push Notifications</label>
        </div>
    </div>

    <div class="mb-3">
        <div class="form-check form-switch">
            <input class="form-check-input" type="checkbox" id="weeklyDigest"
                   checked="@_weeklyDigest"
                   @onchange="e => _weeklyDigest = (bool)(e.Value ?? false)" />
            <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
        </div>
    </div>

    <div class="mb-3">
        <h5>Muted Channels</h5>
        @if (_channels.Count == 0)
        {
            <p class="text-muted">No channels available.</p>
        }
        else
        {
            @foreach (var channel in _channels)
            {
                <div class="form-check">
                    <input class="form-check-input" type="checkbox" id="@($"channel-{channel}")"
                           checked="@_mutedChannels.Contains(channel)"
                           @onchange="e => ToggleMute(channel, (bool)(e.Value ?? false))" />
                    <label class="form-check-label" for="@($"channel-{channel}")">@channel (muted)</label>
                </div>
            }
        }
    </div>

    <button class="btn btn-primary" @onclick="Save">Save Preferences</button>
</section>

@code {
    [Parameter] public NotificationPrefs Prefs { get; set; } = default!;
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private HashSet<string> _mutedChannels = new();
    private List<string> _channels = new();

    // Known channels for demonstration
    private static readonly List<string> AllChannels = new()
    {
        "general", "announcements", "engineering", "marketing", "random"
    };

    protected override void OnParametersSet()
    {
        _emailNotifications = Prefs.EmailNotifications;
        _pushNotifications = Prefs.PushNotifications;
        _weeklyDigest = Prefs.WeeklyDigest;
        _mutedChannels = new HashSet<string>(Prefs.MutedChannels);
        _channels = AllChannels;
    }

    private void ToggleMute(string channel, bool muted)
    {
        if (muted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task Save()
    {
        var prefs = new NotificationPrefs(
            _emailNotifications,
            _pushNotifications,
            _weeklyDigest,
            _mutedChannels.ToList());
        await OnSave.InvokeAsync(prefs);
    }
}

@using sv_009b5a4efa4b41ad8b683981d1471569.Services

<section class="settings-section">
    <h2>Security Settings</h2>

    <!-- Change Password Expandable Panel -->
    <div class="card mb-4">
        <div class="card-header d-flex justify-content-between align-items-center"
             @onclick="() => _passwordPanelOpen = !_passwordPanelOpen"
             style="cursor: pointer;">
            <strong>Change Password</strong>
            <span>@(_passwordPanelOpen ? "▲" : "▼")</span>
        </div>
        @if (_passwordPanelOpen)
        {
            <div class="card-body">
                <div class="mb-3">
                    <label class="form-label">Current Password</label>
                    <input type="password" class="form-control" @bind="_currentPassword" />
                </div>
                <div class="mb-3">
                    <label class="form-label">New Password</label>
                    <input type="password" class="form-control" @bind="_newPassword" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Confirm New Password</label>
                    <input type="password" class="form-control" @bind="_confirmPassword" />
                </div>
                @if (!string.IsNullOrEmpty(_passwordError))
                {
                    <div class="alert alert-danger">@_passwordError</div>
                }
                <button class="btn btn-warning" @onclick="UpdatePassword">Update Password</button>
            </div>
        }
    </div>

    <!-- Two-Factor Authentication -->
    <div class="card mb-4">
        <div class="card-body">
            <div class="d-flex align-items-center justify-content-between">
                <div>
                    <h5 class="mb-1">Two-Factor Authentication</h5>
                    <span class="badge @(Settings.TwoFactorEnabled ? "bg-success" : "bg-secondary")">
                        @(Settings.TwoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                </div>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="twoFactor"
                           checked="@Settings.TwoFactorEnabled" disabled />
                </div>
            </div>
            @if (Settings.LastPasswordChange.HasValue)
            {
                <p class="text-muted mt-2 mb-0">
                    Last password change: @Settings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
                </p>
            }
        </div>
    </div>

    <!-- Active Sessions -->
    <div class="card mb-4">
        <div class="card-header">
            <strong>Active Sessions</strong>
        </div>
        <div class="card-body p-0">
            <div class="table-responsive">
                <table class="table table-striped mb-0">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th>Action</th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in Settings.Sessions)
                        {
                            <tr>
                                <td>@session.Device</td>
                                <td>@session.Location</td>
                                <td>@session.LastActive.ToString("g")</td>
                                <td>
                                    @if (session != Settings.Sessions.FirstOrDefault())
                                    {
                                        <button class="btn btn-sm btn-outline-danger"
                                                @onclick="() => ConfirmRevoke(session.Id)">
                                            Revoke
                                        </button>
                                    }
                                    else
                                    {
                                        <span class="badge bg-info">Current</span>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            </div>
        </div>
    </div>

    <!-- Revoke Confirmation Dialog -->
    @if (_showRevokeConfirm)
    {
        <div class="modal-backdrop fade show"></div>
        <div class="modal fade show d-block" tabindex="-1">
            <div class="modal-dialog modal-dialog-centered">
                <div class="modal-content">
                    <div class="modal-header">
                        <h5 class="modal-title">Confirm Session Revocation</h5>
                        <button type="button" class="btn-close" @onclick="CancelRevoke"></button>
                    </div>
                    <div class="modal-body">
                        <p>Are you sure you want to revoke this session? The device will be signed out immediately.</p>
                    </div>
                    <div class="modal-footer">
                        <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                        <button class="btn btn-danger" @onclick="ExecuteRevoke">Revoke Session</button>
                    </div>
                </div>
            </div>
        </div>
    }
</section>

@code {
    [Parameter] public SecuritySettings Settings { get; set; } = default!;
    [Parameter] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }

    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _passwordError;

    private bool _showRevokeConfirm;
    private string? _pendingRevokeSessionId;

    private async Task UpdatePassword()
    {
        _passwordError = null;

        if (string.IsNullOrWhiteSpace(_currentPassword))
        {
            _passwordError = "Current password is required.";
            return;
        }

        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            _passwordError = "New password is required.";
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            _passwordError = "New password and confirmation do not match.";
            return;
        }

        await OnChangePassword.InvokeAsync((_currentPassword, _newPassword));
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _passwordPanelOpen = false;
    }

    private void ConfirmRevoke(string sessionId)
    {
        _pendingRevokeSessionId = sessionId;
        _showRevokeConfirm = true;
    }

    private void CancelRevoke()
    {
        _showRevokeConfirm = false;
        _pendingRevokeSessionId = null;
    }

    private async Task ExecuteRevoke()
    {
        if (_pendingRevokeSessionId is not null)
        {
            await OnRevokeSession.InvokeAsync(_pendingRevokeSessionId);
        }
        _showRevokeConfirm = false;
        _pendingRevokeSessionId = null;
    }
}

@using sv_009b5a4efa4b41ad8b683981d1471569.Services

<section class="settings-section">
    <h2>Appearance Settings</h2>

    <!-- Theme Selector -->
    <div class="mb-4">
        <h5>Theme</h5>
        @foreach (var theme in new[] { "Light", "Dark", "System" })
        {
            <div class="form-check">
                <input class="form-check-input" type="radio" name="theme" id="@($"theme-{theme}")"
                       value="@theme"
                       checked="@(_theme == theme)"
                       @onchange="() => _theme = theme" />
                <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
            </div>
        }
    </div>

    <!-- Font Size Selector -->
    <div class="mb-4">
        <h5>Font Size</h5>
        @foreach (var size in new[] { "Small", "Medium", "Large" })
        {
            <div class="form-check">
                <input class="form-check-input" type="radio" name="fontSize" id="@($"size-{size}")"
                       value="@size"
                       checked="@(_fontSize == size)"
                       @onchange="() => _fontSize = size" />
                <label class="form-check-label" for="@($"size-{size}")">@size</label>
            </div>
        }
    </div>

    <!-- Language Dropdown -->
    <div class="mb-4">
        <h5>Language</h5>
        <select class="form-select" @bind="_language">
            <option value="English">English</option>
            <option value="Spanish">Spanish</option>
            <option value="French">French</option>
            <option value="German">German</option>
            <option value="Japanese">Japanese</option>
            <option value="Chinese">Chinese</option>
        </select>
    </div>

    <!-- Compact Mode Toggle -->
    <div class="mb-4">
        <div class="form-check form-switch">
            <input class="form-check-input" type="checkbox" id="compactMode"
                   checked="@_compactMode"
                   @onchange="e => _compactMode = (bool)(e.Value ?? false)" />
            <label class="form-check-label" for="compactMode">Compact Mode</label>
        </div>
    </div>

    <!-- Live Preview -->
    <div class="mb-4">
        <h5>Preview</h5>
        <div class="appearance-preview @GetPreviewClasses()">
            <div class="preview-header">Settings Dashboard</div>
            <div class="preview-text">
                This is a preview of how your content will look with the selected appearance settings.
            </div>
            <div class="preview-meta">
                Theme: @_theme | Font: @_fontSize | Language: @_language | Compact: @(_compactMode ? "On" : "Off")
            </div>
        </div>
    </div>

    <button class="btn btn-primary" @onclick="Save">Save</button>
</section>

@code {
    [Parameter] public AppearanceSettings Settings { get; set; } = default!;
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    protected override void OnParametersSet()
    {
        _theme = Settings.Theme;
        _fontSize = Settings.FontSize;
        _language = Settings.Language;
        _compactMode = Settings.CompactMode;
    }

    private string GetPreviewClasses()
    {
        var classes = new List<string>();

        classes.Add(_theme switch
        {
            "Dark" => "preview-dark",
            "Light" => "preview-light",
            _ => "preview-system"
        });

        classes.Add(_fontSize switch
        {
            "Small" => "preview-font-small",
            "Large" => "preview-font-large",
            _ => "preview-font-medium"
        });

        if (_compactMode) classes.Add("preview-compact");

        return string.Join(" ", classes);
    }

    private async Task Save()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await OnSave.InvokeAsync(settings);
    }
}

