toolArgs.file_text:
@using sv_009b5a4efa4b41ad8b683981d1471569.Services

<section class="settings-section">
    <h2>Appearance Settings</h2>

    <!-- Theme Selector -->
    <div class="mb-4">
        <h5>Theme</h5>
        @foreach (var theme in new[] { "Light", "Dark", "System" })
        {
            <div class="form-check">
                <input class="form-check-input" type="radio" name="theme" id="@($"theme-{theme}")"
                       value="@theme"
                       checked="@(_theme == theme)"
                       @onchange="() => _theme = theme" />
                <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
            </div>
        }
    </div>

    <!-- Font Size Selector -->
    <div class="mb-4">
        <h5>Font Size</h5>
        @foreach (var size in new[] { "Small", "Medium", "Large" })
        {
            <div class="form-check">
                <input class="form-check-input" type="radio" name="fontSize" id="@($"size-{size}")"
                       value="@size"
                       checked="@(_fontSize == size)"
                       @onchange="() => _fontSize = size" />
                <label class="form-check-label" for="@($"size-{size}")">@size</label>
            </div>
        }
    </div>

    <!-- Language Dropdown -->
    <div class="mb-4">
        <h5>Language</h5>
        <select class="form-select" @bind="_language">
            <option value="English">English</option>
            <option value="Spanish">Spanish</option>
            <option value="French">French</option>
            <option value="German">German</option>
            <option value="Japanese">Japanese</option>
            <option value="Chinese">Chinese</option>
        </select>
    </div>

    <!-- Compact Mode Toggle -->
    <div class="mb-4">
        <div class="form-check form-switch">
            <input class="form-check-input" type="checkbox" id="compactMode"
                   checked="@_compactMode"
                   @onchange="e => _compactMode = (bool)(e.Value ?? false)" />
            <label class="form-check-label" for="compactMode">Compact Mode</label>
        </div>
    </div>

    <!-- Live Preview -->
    <div class="mb-4">
        <h5>Preview</h5>
        <div class="appearance-preview @GetPreviewClasses()">
            <div class="preview-header">Settings Dashboard</div>
            <div class="preview-text">
                This is a preview of how your content will look with the selected appearance settings.
            </div>
            <div class="preview-meta">
                Theme: @_theme | Font: @_fontSize | Language: @_language | Compact: @(_compactMode ? "On" : "Off")
            </div>
        </div>
    </div>

    <button class="btn btn-primary" @onclick="Save">Save</button>
</section>

@code {
    [Parameter] public AppearanceSettings Settings { get; set; } = default!;
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    protected override void OnParametersSet()
    {
        _theme = Settings.Theme;
        _fontSize = Settings.FontSize;
        _language = Settings.Language;
        _compactMode = Settings.CompactMode;
    }

    private string GetPreviewClasses()
    {
        var classes = new List<string>();

        classes.Add(_theme switch
        {
            "Dark" => "preview-dark",
            "Light" => "preview-light",
            _ => "preview-system"
        });

        classes.Add(_fontSize switch
        {
            "Small" => "preview-font-small",
            "Large" => "preview-font-large",
            _ => "preview-font-medium"
        });

        if (_compactMode) classes.Add("preview-compact");

        return string.Join(" ", classes);
    }

    private async Task Save()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await OnSave.InvokeAsync(settings);
    }
}

