.settings-dashboard {
    min-height: 80vh;
}

/* Sidebar Navigation */
.settings-sidebar {
    width: 220px;
    min-width: 220px;
    border-right: 1px solid #dee2e6;
    padding: 1rem 0;
    background-color: #f8f9fa;
}

.settings-sidebar .nav-link {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.75rem 1.25rem;
    color: #495057;
    border: none;
    background: none;
    width: 100%;
    text-align: left;
    font-size: 0.95rem;
    border-left: 3px solid transparent;
    transition: all 0.2s ease;
}

.settings-sidebar .nav-link:hover {
    background-color: #e9ecef;
    color: #212529;
}

.settings-sidebar .nav-link.active {
    background-color: #e7f1ff;
    color: #0d6efd;
    border-left-color: #0d6efd;
    font-weight: 600;
}

.section-icon {
    font-size: 1.1rem;
}

/* Main Content */
.settings-content {
    padding: 2rem;
    position: relative;
}

.settings-section h2 {
    margin-bottom: 1.5rem;
    padding-bottom: 0.75rem;
    border-bottom: 1px solid #dee2e6;
}

/* Avatar */
.avatar-preview {
    width: 100px;
    height: 100px;
